#!/usr/bin/env node
// Generates the temporary blog fixtures for the build matrix (04 §3, §9) and removes
// them again. Fixtures are NEVER committed: every generated file is named `qa-*`,
// carries the marker below, and `clean` deletes exactly those files.
//
// Usage:
//   node tests/scripts/fixtures.mjs b1            # qa-published, qa-future (+30 d), qa-draft
//   node tests/scripts/fixtures.mjs b1x           # b1 + ordering/year-boundary, edge and hostile posts
//   node tests/scripts/fixtures.mjs b3 <case>     # one invalid post; cases: see `list`
//   node tests/scripts/fixtures.mjs list
//   node tests/scripts/fixtures.mjs clean         # remove every generated fixture
//
// Writes only under content/blog/ (and nothing under public/). Refuses to overwrite a
// file it did not create.

import { existsSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

export const MARKER = "# qa-fixture: generated by tests/scripts/fixtures.mjs; never commit";

const repo = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
const blogDir = path.join(repo, "content/blog");

const DAY = 86_400_000;
const iso = (ms) => new Date(ms).toISOString().replace(/\.\d{3}Z$/, "Z");

/** Front matter with the marker as the first YAML line, so `clean` can recognise it. */
function post(fields, body = "Fixture body. It has a [link](https://example.com/) and some *emphasis*.\n") {
  const lines = [MARKER];
  for (const [k, v] of Object.entries(fields)) {
    if (v === undefined) continue;
    lines.push(`${k}: ${Array.isArray(v) ? `[${v.join(", ")}]` : typeof v === "string" ? JSON.stringify(v) : v}`);
  }
  return `---\n${lines.join("\n")}\n---\n${body}`;
}

const valid = (over = {}) => ({
  title: "QA published fixture",
  date: iso(Date.now() - 2 * DAY),
  summary: "A published fixture post used by the QA build matrix.",
  tags: ["testing"],
  draft: false,
  ...over,
});

const B1 = () => ({
  "qa-published.md": post(valid()),
  "qa-future.md": post(valid({ title: "QA future fixture", date: iso(Date.now() + 30 * DAY) })),
  "qa-draft.md": post(valid({ title: "QA draft fixture", draft: true })),
});

const HOSTILE = [
  "[js link](javascript:alert(1))",
  "[js upper](JAVASCRIPT:alert(1))",
  "[js entity](&#106;avascript:alert(1))",
  "[js tab](java\tscript:alert(1))",
  "![img](x\" onerror=\"alert(1))",
  "<img src=x onerror=alert(1)>",
  "<script>alert(1)</script>",
  "<iframe src=\"https://example.com\"></iframe>",
  "<svg onload=alert(1)></svg>",
  "[svg](data:image/svg+xml;base64,PHN2ZyBvbmxvYWQ9YWxlcnQoMSk+PC9zdmc+)",
  "![svg img](data:image/svg+xml,<svg onload=alert(1)>)",
  "[ref link][evil]\n\n[evil]: javascript:alert(1)",
  "[vb](vbscript:msgbox(1))",
  "<a href=\"javascript:alert(1)\">raw anchor</a>",
  "<div style=\"background:url(javascript:alert(1))\">styled</div>",
  "<details open ontoggle=alert(1)>x</details>",
  "&lt;script&gt;alert(1)&lt;/script&gt;",
  "<math><mi xlink:href=\"javascript:alert(1)\">x</mi></math>",
  "[data html](data:text/html,<script>alert(1)</script>)",
  "<form action=\"javascript:alert(1)\"><button>go</button></form>",
];

const B1X = () => ({
  ...B1(),
  // Ordering and year grouping across a boundary (BLG-02).
  "qa-order-old.md": post(valid({ title: "QA order: last day of 2025", date: "2025-12-31T23:30:00Z" })),
  "qa-order-new.md": post(valid({ title: "QA order: first day of 2026", date: "2026-01-01T00:30:00Z" })),
  // BLG-07 layout/safety and BLG-11 UTC date. The plan's 2026-11-01T23:30Z is in the
  // future at the time of writing, so the same clock time a year earlier is used.
  "qa-edge.md": post(
    valid({
      title: "QA edge: a very long title that keeps going so the heading must wrap at 320px wide",
      date: "2025-11-01T23:30:00Z",
    }),
    [
      "Unbroken: " + "x".repeat(100),
      "",
      "| a | b | c | d | e | f | g | h | i | j | k | l |",
      "|---|---|---|---|---|---|---|---|---|---|---|---|",
      "| 1111111111 | 2222222222 | 3333333333 | 4444444444 | 5555555555 | 6666666666 | 7777777777 | 8888888888 | 9999999999 | 0000000000 | aaaaaaaaaa | bbbbbbbbbb |",
      "",
      "```js",
      "const line = '" + "y".repeat(200) + "';",
      "```",
      "",
      "Text that looks like code: <script>window.__qaPwned = 1</script> and <img src=x onerror=\"window.__qaPwned=1\">.",
      "",
    ].join("\n"),
  ),
  // SEC-07: 20 hostile snippets, one paragraph each.
  "qa-hostile.md": post(
    valid({ title: "QA hostile markdown", date: iso(Date.now() - 3 * DAY) }),
    HOSTILE.join("\n\n") + "\n",
  ),
});

/** B3: each case must FAIL the build with a message containing `expect` (file and field). */
export const B3_CASES = {
  "no-summary": {
    files: { "qa-invalid.md": post(valid({ summary: undefined })) },
    expect: ["content/blog/qa-invalid.md", "summary"],
  },
  "bad-date": {
    files: { "qa-invalid.md": post(valid({ date: "next tuesday" })) },
    expect: ["content/blog/qa-invalid.md", "date"],
  },
  // A true duplicate slug cannot exist on one filesystem (the slug is the filename),
  // and macOS is case-insensitive. The nearest reachable collision is a second file
  // for the same slug with a non-.md Markdown extension, which the loader rejects.
  "dup-slug": {
    files: { "qa-dup.md": post(valid()), "qa-dup.markdown": post(valid()) },
    expect: ["content/blog/qa-dup.markdown", ".md"],
  },
  "cover-no-alt": {
    files: { "qa-invalid.md": post(valid({ cover: "/images/blog/hello-world/blocks.png" })) },
    expect: ["content/blog/qa-invalid.md", "coverAlt"],
  },
  "missing-image": {
    files: {
      "qa-invalid.md": post(valid(), "![missing](/images/blog/qa-invalid/does-not-exist.png)\n"),
    },
    expect: ["content/blog/qa-invalid.md", "does-not-exist.png"],
  },
  "bad-tag": {
    files: { "qa-invalid.md": post(valid({ tags: ["Foo Bar"] })) },
    expect: ["content/blog/qa-invalid.md", "tags"],
  },
};

export function generatedFiles() {
  if (!existsSync(blogDir)) return [];
  return readdirSync(blogDir)
    .filter((n) => n.startsWith("qa-"))
    .filter((n) => readFileSync(path.join(blogDir, n), "utf8").includes(MARKER))
    .map((n) => path.join(blogDir, n));
}

export function clean() {
  const files = generatedFiles();
  for (const f of files) rmSync(f);
  return files;
}

export function write(files) {
  for (const [name, content] of Object.entries(files)) {
    const target = path.join(blogDir, name);
    if (existsSync(target) && !readFileSync(target, "utf8").includes(MARKER)) {
      throw new Error(`fixtures: refusing to overwrite ${target}: it is not a generated fixture`);
    }
    writeFileSync(target, content);
  }
  return Object.keys(files).map((n) => path.join("content/blog", n));
}

export function apply(set, caseName) {
  clean();
  if (set === "b0" || set === "b2" || set === "b4") return [];
  if (set === "b1") return write(B1());
  if (set === "b1x") return write(B1X());
  if (set === "b3") {
    const c = B3_CASES[caseName];
    if (!c) throw new Error(`fixtures: unknown b3 case "${caseName}"; one of ${Object.keys(B3_CASES).join(", ")}`);
    return write(c.files);
  }
  throw new Error(`fixtures: unknown set "${set}"`);
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const [cmd, arg] = process.argv.slice(2);
  try {
    if (cmd === "clean") {
      const removed = clean();
      console.log(removed.length ? `removed ${removed.length} fixture(s)` : "no fixtures present");
    } else if (cmd === "list") {
      console.log("sets: b0 b1 b1x b2 b4 (no files for b0/b2/b4); b3 cases:");
      for (const [k, v] of Object.entries(B3_CASES)) console.log(`  ${k}: expects ${v.expect.join(" + ")}`);
    } else if (cmd) {
      for (const f of apply(cmd, arg)) console.log(`wrote ${f}`);
    } else {
      console.error("usage: fixtures.mjs b1|b1x|b3 <case>|list|clean");
      process.exit(2);
    }
  } catch (err) {
    console.error(err.message);
    process.exit(1);
  }
}
